from pathlib import Path
root=Path(__file__).parent
out=root/'mockups'
out.mkdir(exist_ok=True)
css='''*{box-sizing:border-box}body{margin:0;background:#f8fafc;color:#0f172a;font:16px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif} .banner{background:#0f172a;color:white;padding:12px 28px;font-size:14px;letter-spacing:.2px}.shell{display:flex;min-height:820px}aside{width:220px;background:white;border-right:1px solid #d9e1ec;padding:30px 22px;flex-shrink:0}aside h2{font-size:22px;margin:0 0 36px}.nav{padding:13px 14px;margin:5px 0;border-radius:8px;color:#475569}.nav.sel{color:#1e40af;background:#eff6ff;font-weight:650}.main{padding:28px 38px;flex:1;min-width:0}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:26px}h1{font-size:30px;letter-spacing:-.6px;margin:6px 0 10px}h2{font-size:19px;margin:0 0 14px}p{line-height:1.55;color:#475569;margin:8px 0}.eyebrow{font-size:13px;letter-spacing:.8px;font-weight:650;color:#475569}.muted{color:#475569;font-size:14px}.btn{display:inline-block;border:1px solid #cbd5e1;border-radius:8px;padding:12px 18px;background:white;color:#0f172a;font-weight:600;font-size:14px}.btn.blue{background:#2563eb;color:white;border-color:#2563eb}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:white;border:1px solid #cbd5e1;border-radius:12px;padding:23px;margin-bottom:20px}.tabs{display:flex;gap:26px;border-bottom:1px solid #cbd5e1;margin:24px 0}.tabs span{padding:12px 0;color:#475569}.tabs .sel{border-bottom:3px solid #2563eb;color:#1e40af;font-weight:650}.tag{font-size:12px;color:#1e40af;background:#eff6ff;padding:6px 9px;border-radius:6px}.number{font-size:30px;font-weight:700;margin:10px 0}.field{margin-bottom:18px}label{display:block;font-size:14px;font-weight:650;margin-bottom:8px}input,select{padding:12px;border:1px solid #94a3b8;background:white;border-radius:7px;font:16px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;width:100%;color:#0f172a}input:focus{outline:3px solid #2563eb}.error{font-size:14px;color:#991b1b;margin-top:7px}.row{display:flex;gap:15px;align-items:center}.row>*{flex:1}.rule{border-top:1px solid #e2e8f0;margin:20px 0}.good{color:#065f46}.summary{background:#f8fafc;padding:15px;border-radius:8px;margin:12px 0}.numfield{display:flex;gap:16px;align-items:center}.numfield input[type=range]{flex:1;padding:0}.numfield input[type=number]{width:125px}.footer{margin-top:20px;font-size:13px;color:#475569}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;border-bottom:1px solid #e2e8f0;padding:15px 9px}th{background:#f8fafc}.focus{outline:3px solid #2563eb;outline-offset:3px}.item{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #e2e8f0}.pill{border:1px solid #94a3b8;border-radius:30px;padding:8px 12px;font-size:13px}.auth{max-width:520px;margin:38px auto;background:white;border:1px solid #cbd5e1;border-radius:14px;padding:32px}.steps{font-size:14px;color:#1e40af;margin:18px 0}.hint{font-size:13px;line-height:1.5;color:#475569;margin-top:8px}'''
def page(name,title,body,active='Overview',shell=True):
    nav=''.join(f'<div class="nav {"sel" if x==active else ""}">{x}</div>' for x in ['Overview','Activity','Insights','Plan','Reports','Family','Profile','Settings'])
    content=f'<div class="shell"><aside><h2>FINAURA</h2>{nav}</aside><div class="main">{body}</div></div>' if shell else body
    (out/(name+'.html')).write_text(f'<!doctype html><html><meta charset="utf-8"><title>{title}</title><style>{css}</style><div class="banner">EXPERIMENT 8 &nbsp; / &nbsp; PROPOSED UI MOCKUP &nbsp; / &nbsp; {title} &nbsp; / &nbsp; Illustrative data</div>{content}</html>')
page('overview','Overview', '''<div class="top"><div><div class="eyebrow">PERSONAL OVERVIEW</div><h1>Your financial picture</h1><p>October 2026 · Personal account</p></div><div class="btn blue">+ Record expense</div></div><div class="grid"><div class="card"><span class="muted">Current balance · all recorded activity</span><div class="number">₹20,000</div><p>Updated today at 11:45 pm</p></div><div class="card"><span class="muted">Financial Maturity Index · this month</span><div class="number">84 <span class="muted">/ 100</span></div><p class="good">1 recorded snapshot · comparison unavailable</p><span class="tag">View the three score factors →</span></div></div><div class="card"><h2>Your next step</h2><p>Record your first expense to begin building spending insights.</p><div class="btn">Record first expense</div><span class="muted"> &nbsp; Personal ledger · no financial transfer is made</span></div><div class="grid"><div class="card"><h2>Cash flow this month</h2><div class="item"><span>Recorded income</span><b>₹0</b></div><div class="item"><span>Recorded outflow</span><b>₹0</b></div><div class="item"><span>Net flow</span><b>₹0</b></div><p class="hint">1–15 October 2026 · Includes investments in outflow</p></div><div class="card"><h2>Upcoming bills</h2><div class="item"><span>No recurring bills recorded</span><b>—</b></div><div class="item"><span>Add a bill to track its due date</span><b>—</b></div><div class="footer">Open recurring bills →</div></div></div><div class="footer">D01 terminology and time context · D04 readable secondary text · D08 action hierarchy</div>''')
page('activity','Transactions', '''<div class="top"><div><div class="eyebrow">ACTIVITY</div><h1>Transactions</h1><p>Find an entry, check its classification, or record an expense.</p></div><div class="btn blue">+ Record expense</div></div><div class="tabs"><span class="sel">Transactions</span><span>Income</span><span>Recurring bills</span></div><div class="card"><div class="row"><div><label>Search transactions</label><input value="groceries"></div><div><label>Period</label><select><option>This month</option></select></div><div><label>Category</label><select><option>All categories</option></select></div></div><div class="row" style="margin-top:18px"><span class="pill">Search: groceries ×</span><span class="pill">October 2026 ×</span><span class="muted">Clear filters</span></div><p class="hint">Filters and sort order remain in the URL when you reload or return.</p></div><div class="card"><div class="row"><div><span class="muted">Matching records</span><div class="number">0</div></div><div><span class="muted">Filtered outflow</span><div class="number">₹0</div></div><div><span class="muted">Period</span><div style="font-size:20px;margin-top:10px">1–15 October 2026</div></div></div><table><tr><th>Entry</th><th>Classification</th><th>Amount</th><th>Actions</th></tr><tr><td colspan="4"><b>No matching transactions</b><p>No entries are recorded yet. Record an expense to begin.</p><span class="btn">Record first expense</span></td></tr></table><p class="hint">0 matching records · filters remain active</p></div><div class="footer">D05 durable filters · D06 explicit classification review · D08 clear task hierarchy</div>''',active='Activity')
page('scenario','Scenario comparison', '''<div class="top"><div><div class="eyebrow">PLAN</div><h1>Test a retirement scenario</h1><p>Changes apply to this simulation. Your saved profile stays unchanged.</p></div><span class="tag">Unsaved scenario</span></div><div class="tabs"><span>Net worth</span><span>Assets</span><span>Goals</span><span>Retirement</span><span class="sel">Scenario Lab</span></div><div class="grid"><div class="card"><h2>Change assumptions</h2><div class="field"><label>Monthly investment · INR</label><div class="numfield"><input type="range" value="35"><input type="number" value="12750"></div><p class="hint">Enter an exact amount or use the slider.</p></div><div class="field"><label>Retirement age · years</label><div class="numfield"><input type="range" value="50"><input type="number" value="60"></div></div><div class="row"><div class="field"><label>Annual return · %</label><input type="number" value="8"></div><div class="field"><label>Annual inflation · %</label><input type="number" value="6"></div></div><p class="hint">Advanced contribution assumptions ▾</p><div class="rule"></div><div class="btn blue">Run simulation</div> <div class="btn">Reset</div></div><div class="card"><h2>Compare with your saved baseline</h2><p class="muted">Input preview · no result calculated</p><table><tr><th>Measure</th><th>Baseline</th><th>Scenario</th></tr><tr><td>Monthly investment</td><td>Not set</td><td>₹12,750 input</td></tr><tr><td>Target age</td><td>60</td><td>60</td></tr><tr><td>Target funding probability</td><td>Unavailable</td><td>Not calculated</td></tr></table><p class="good">Add the required profile details to calculate a comparison.</p><p class="hint">Projection based on selected return and inflation assumptions. Outcomes remain uncertain.</p><div class="summary">Awaiting profile data · no funding conclusion available</div></div></div><div class="footer">D07 exact numeric input · D01 explicit units · D14 visible calculation status</div>''',active='Plan')
page('form','Accessible transaction form', '''<div class="auth"><div class="eyebrow">ACTIVITY / RECORD EXPENSE</div><h1>Record expense</h1><p>Enter the payment details, then review the category.</p><div class="steps">1 Details &nbsp; → &nbsp; 2 Review classification</div><div class="field"><label>Amount · INR *</label><input value="0" style="border-color:#991b1b" aria-invalid="true"><div class="error">Enter an amount greater than ₹0.</div></div><div class="field"><label>Description or merchant</label><input value="Weekly grocery shop"><div class="hint">Use the merchant or purpose to help classify this entry.</div></div><div class="field"><label>Date</label><input value="15 October 2026"></div><div class="summary"><b>Suggested category</b><p>Groceries · Need</p><p class="hint">Suggested from the description. Check it before saving.</p><span class="btn">Use suggestion</span> <span class="btn">Choose manually</span></div><div class="row"><span class="btn">Cancel</span><span class="btn blue focus">Review and save</span></div><p class="hint">Keyboard focus stays inside this dialog. Closing it returns focus to Record expense.</p></div><p style="text-align:center" class="footer">D02 focus management · D03 linked field error · D06 user controlled classification</p>''',shell=False)
print(out)
